import type { TravelSession } from '../utils/travelSession'

interface Props {
  session: TravelSession
}

function statusText(completion: number): string {
  if (completion >= 100) return 'الخطة جاهزة للتأكيد'
  if (completion >= 60) return 'الخطة شبه مكتملة'
  return 'نحتاج بعض المعلومات'
}

function statusColor(completion: number): string {
  if (completion >= 100) return 'text-success-600'
  if (completion >= 60) return 'text-primary-600'
  return 'text-amber-600'
}

export default function PlanningProgressCard({ session }: Props) {
  const completion = session.completionPercentage
  const status = statusText(completion)

  return (
    <section className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <span className="text-base">📊</span>
          <h2 className="text-sm font-bold text-slate-900">اكتمال خطة الرحلة</h2>
        </div>
        <span className={`text-sm font-bold ${statusColor(completion)}`}>
          {status}
        </span>
      </div>
      <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-slate-100">
        <div
          className="h-full rounded-full bg-gradient-to-l from-primary-400 to-primary-600 transition-all duration-700 ease-out"
          style={{ width: `${completion}%` }}
        />
      </div>
      <p className="mt-1.5 text-left text-xs font-medium text-slate-400">{completion}%</p>
    </section>
  )
}

import { memo, useMemo } from 'react'
import {
  getDisplayValue,
  SESSION_FIELD_LABELS,
  type TravelSession,
} from '../utils/travelSession'

interface Props {
  session: TravelSession
}

const PRIMARY_FIELDS: (keyof TravelSession)[] = [
  'destination',
  'departureCity',
  'departureDate',
  'durationDays',
  'adults',
  'children',
  'budgetAmount',
  'budgetCurrency',
  'tripPurpose',
]

const PREFERENCE_FIELDS: (keyof TravelSession)[] = [
  'cabinClass',
  'preferredHotelCategory',
  'accommodationPreference',
  'transportPreference',
  'directFlightPreference',
  'baggagePreference',
  'visaStatus',
  'interests',
]

function isFilled(session: TravelSession, field: keyof TravelSession): boolean {
  const val = session[field]
  if (val === null || val === undefined || val === '') return false
  if (typeof val === 'number' && val === 0) return false
  if (Array.isArray(val) && val.length === 0) return false
  return true
}

function PremiumLiveSummaryCardImpl({ session }: Props) {
  const primaryItems = useMemo(() => {
    return PRIMARY_FIELDS.map(field => ({
      field,
      label: SESSION_FIELD_LABELS[String(field)] ?? String(field),
      value: getDisplayValue(field, session),
      filled: isFilled(session, field),
    }))
  }, [session])

  const preferenceItems = useMemo(() => {
    return PREFERENCE_FIELDS.map(field => ({
      field,
      label: SESSION_FIELD_LABELS[String(field)] ?? String(field),
      value: getDisplayValue(field, session),
      filled: isFilled(session, field),
    }))
  }, [session])

  const filledCount = [...primaryItems, ...preferenceItems].filter(i => i.filled).length
  const totalCount = primaryItems.length + preferenceItems.length
  const completionPercent = Math.round((filledCount / totalCount) * 100)

  const profileReady = session.decisionProfileConfirmed

  return (
    <section
      aria-labelledby="summary-heading"
      className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm"
    >
      <div className="mb-4 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-base">📋</span>
          <h3 id="summary-heading" className="text-sm font-bold text-slate-900">ملخص رحلتك المباشر</h3>
        </div>
        {profileReady && (
          <span className="rounded-full bg-success-100 px-2.5 py-0.5 text-[10px] font-bold text-success-700">
            مؤكد
          </span>
        )}
      </div>

      {/* Completion ring */}
      <div className="mb-4 flex items-center justify-between rounded-xl bg-slate-50/60 px-4 py-3">
        <div>
          <p className="text-[10px] font-medium text-slate-400">اكتمال الملف</p>
          <p className="text-xl font-bold text-slate-800">{completionPercent}%</p>
        </div>
        <div className="relative h-12 w-12">
          <svg viewBox="0 0 44 44" className="h-12 w-12 -rotate-90">
            <circle cx="22" cy="22" r="18" fill="none" stroke="#e2e8f0" strokeWidth="3" />
            <circle
              cx="22"
              cy="22"
              r="18"
              fill="none"
              stroke="currentColor"
              strokeWidth="3"
              strokeLinecap="round"
              className="text-primary-500 transition-all duration-700"
              strokeDasharray={`${(completionPercent / 100) * 113} 113`}
            />
          </svg>
          <span className="absolute inset-0 flex items-center justify-center text-[10px] font-bold text-primary-600">
            {filledCount}/{totalCount}
          </span>
        </div>
      </div>

      {/* Primary fields */}
      <div className="mb-4">
        <p className="mb-2 text-[10px] font-bold text-slate-400">المعلومات الأساسية</p>
        <div className="grid grid-cols-2 gap-2">
          {primaryItems.map(item => (
            <div
              key={String(item.field)}
              className={`rounded-lg border px-3 py-2 transition-all duration-300 ${
                item.filled
                  ? 'border-emerald-100 bg-emerald-50/40'
                  : 'border-slate-100 bg-slate-50/30'
              }`}
            >
              <p className="text-[9px] font-medium text-slate-400">{item.label}</p>
              <p className={`mt-0.5 truncate text-xs font-bold ${
                item.filled ? 'text-slate-800' : 'text-slate-300'
              }`}>
                {item.filled ? item.value : '—'}
              </p>
            </div>
          ))}
        </div>
      </div>

      {/* Preference fields */}
      <div>
        <p className="mb-2 text-[10px] font-bold text-slate-400">التفضيلات</p>
        <div className="flex flex-wrap gap-1.5">
          {preferenceItems.map(item => (
            <span
              key={String(item.field)}
              className={`rounded-full border px-2.5 py-1 text-[10px] font-medium transition-all duration-300 ${
                item.filled
                  ? 'border-primary-200 bg-primary-50 text-primary-700'
                  : 'border-slate-100 bg-slate-50 text-slate-300'
              }`}
            >
              {item.filled ? `${item.label}: ${item.value}` : item.label}
            </span>
          ))}
        </div>
      </div>
    </section>
  )
}

export const PremiumLiveSummaryCard = memo(PremiumLiveSummaryCardImpl)

import { memo, useMemo } from 'react'
import type { NormalizedTravelOption } from '../utils/searchOrchestrator'
import type { ReasoningResult } from '../utils/reasoningEngine'
import type { TravelSearchRequest } from '../utils/travelSearchRequest'
import { buildFullReport, scoreToStars, formatStars } from '../utils/reportFormatter'

interface Props {
  rankedOptions: NormalizedTravelOption[]
  reasoningResults: Map<string, ReasoningResult>
  searchRequest: TravelSearchRequest
}

const TYPE_LABELS: Record<string, string> = {
  flight: 'طيران',
  hotel: 'فندق',
  activity: 'نشاط',
  transportation: 'مواصلات',
}

const CATEGORY_LABELS: Record<string, string> = {
  price: 'الميزانية',
  comfort: 'الراحة',
  travelTime: 'وقت السفر',
  familySuitability: 'العائلة',
  luxury: 'الفخامة',
  destinationMatch: 'الوجهة',
  purposeMatch: 'الغرض',
  preferenceMatch: 'التفضيلات',
}

function PrintableReportImpl({ rankedOptions, reasoningResults, searchRequest }: Props) {
  const reports = useMemo(
    () => buildFullReport(rankedOptions, reasoningResults),
    [rankedOptions, reasoningResults],
  )

  const reportDate = new Date().toLocaleDateString('ar-SA')

  return (
    <div className="print-report hidden print:block" dir="rtl" aria-label="تقرير قابل للطباعة">
      {/* Header */}
      <div className="mb-6 border-b-2 border-slate-800 pb-4">
        <h1 className="text-2xl font-bold text-slate-900">رحّال — تقرير التوصيات</h1>
        <p className="mt-1 text-sm text-slate-500">تاريخ التقرير: {reportDate}</p>
      </div>

      {/* Trip summary */}
      <div className="mb-6">
        <h2 className="mb-3 text-lg font-bold text-slate-800">ملخص الرحلة</h2>
        <table className="w-full text-sm">
          <tbody>
            <tr><td className="py-1 font-semibold text-slate-600">الوجهة:</td><td className="py-1 text-slate-800">{searchRequest.destination}</td></tr>
            <tr><td className="py-1 font-semibold text-slate-600">مدينة المغادرة:</td><td className="py-1 text-slate-800">{searchRequest.departureCity}</td></tr>
            <tr><td className="py-1 font-semibold text-slate-600">المدة:</td><td className="py-1 text-slate-800">{searchRequest.durationDays} يوم</td></tr>
            <tr><td className="py-1 font-semibold text-slate-600">المسافرون:</td><td className="py-1 text-slate-800">{searchRequest.travelers.adults} بالغ، {searchRequest.travelers.children} طفل</td></tr>
            <tr><td className="py-1 font-semibold text-slate-600">الميزانية:</td><td className="py-1 text-slate-800" dir="ltr">{searchRequest.budgetAmount.toLocaleString()} {searchRequest.budgetCurrency}</td></tr>
            <tr><td className="py-1 font-semibold text-slate-600">اكتمال البيانات:</td><td className="py-1 text-slate-800" dir="ltr">{searchRequest.completionPercentage}%</td></tr>
          </tbody>
        </table>
      </div>

      {/* Ranked options */}
      <div>
        <h2 className="mb-3 text-lg font-bold text-slate-800">التوصيات المرتّبة</h2>
        {reports.map((report, i) => {
          const stars = formatStars(scoreToStars(report.overallScore))
          return (
            <div key={report.optionId} className="mb-5 border border-slate-300 p-4">
              <div className="flex items-start justify-between">
                <div>
                  <h3 className="text-base font-bold text-slate-900">
                    {i + 1}. {report.optionTitle}
                  </h3>
                  <p className="text-xs text-slate-500">{TYPE_LABELS[report.optionType] ?? report.optionType}</p>
                </div>
                <div className="text-left">
                  <p className="text-lg font-bold text-slate-900" dir="ltr">{report.price.toLocaleString()} {report.currency}</p>
                  <p className="text-sm text-amber-500" dir="rtl">{stars.visual}</p>
                </div>
              </div>

              <p className="mt-1 text-sm font-semibold text-slate-700">
                التقييم الإجمالي: <span dir="ltr">{report.overallScore}/100</span> — {report.recommendationLabel}
              </p>

              {/* Why Rahhal recommends */}
              {report.whyRahhalRecommends.length > 0 && (
                <div className="mt-3">
                  <p className="text-xs font-bold text-slate-600">لماذا يوصي به رحّال:</p>
                  <ul className="mt-1 list-inside list-disc text-xs text-slate-700">
                    {report.whyRahhalRecommends.map((text, j) => <li key={j}>{text}</li>)}
                  </ul>
                </div>
              )}

              {/* Strengths */}
              {report.advantages.length > 0 && (
                <div className="mt-2">
                  <p className="text-xs font-bold text-emerald-700">نقاط القوة:</p>
                  <ul className="mt-1 list-inside list-disc text-xs text-slate-700">
                    {report.advantages.map((text, j) => <li key={j}>{text}</li>)}
                  </ul>
                </div>
              )}

              {/* Weaknesses */}
              {report.disadvantages.length > 0 && (
                <div className="mt-2">
                  <p className="text-xs font-bold text-rose-700">نقاط الضعف:</p>
                  <ul className="mt-1 list-inside list-disc text-xs text-slate-700">
                    {report.disadvantages.map((text, j) => <li key={j}>{text}</li>)}
                  </ul>
                </div>
              )}

              {/* Best suited for */}
              {report.bestSuitedFor.length > 0 && (
                <div className="mt-2">
                  <p className="text-xs font-bold text-slate-600">مناسب لـ:</p>
                  <p className="text-xs text-slate-700">{report.bestSuitedFor.join('، ')}</p>
                </div>
              )}

              {/* Category scores */}
              {(() => {
                const opt = rankedOptions.find(o => o.id === report.optionId)
                if (!opt?.decisionScore) return null
                return (
                  <div className="mt-3">
                    <p className="text-xs font-bold text-slate-600">تفصيل النقاط:</p>
                    <table className="mt-1 w-full text-xs">
                      <tbody>
                        {opt.decisionScore.categories.map(cat => (
                          <tr key={cat.category}>
                            <td className="py-0.5 text-slate-600">{CATEGORY_LABELS[cat.category] ?? cat.category}</td>
                            <td className="py-0.5 text-left font-semibold text-slate-800" dir="ltr">{cat.score}/100</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )
              })()}
            </div>
          )
        })}
      </div>

      {/* Footer */}
      <div className="mt-6 border-t border-slate-300 pt-3 text-center">
        <p className="text-xs text-slate-400">هذا التقرير تم إنشاؤه بواسطة رحّال — مستشار السفر الذكي</p>
      </div>
    </div>
  )
}

export const PrintableReport = memo(PrintableReportImpl)

import { memo, useMemo } from 'react'
import {
  getNextBestQuestion,
  getNextOptionalQuestion,
  getMissingFields,
  isDecisionProfileReady,
  SESSION_FIELD_LABELS,
  type TravelSession,
} from '../utils/travelSession'

interface Props {
  session: TravelSession
}

function confidenceLevel(session: TravelSession): { label: string; color: string; percent: number } {
  const knownFields = session.completedFields.length
  const totalTracked = session.explicitFields.length + session.inferredFields.length
  if (totalTracked === 0) return { label: 'غير محدد', color: 'text-slate-400', percent: 0 }
  const ratio = Math.min(knownFields / Math.max(totalTracked, 1), 1)
  if (ratio >= 0.8) return { label: 'مرتفعة', color: 'text-emerald-600', percent: Math.round(ratio * 100) }
  if (ratio >= 0.5) return { label: 'متوسطة', color: 'text-amber-600', percent: Math.round(ratio * 100) }
  return { label: 'منخفضة', color: 'text-rose-500', percent: Math.round(ratio * 100) }
}

function recommendationQuality(session: TravelSession): { label: string; stars: string } {
  if (session.completionPercentage >= 90) return { label: 'ممتازة', stars: '★★★★★' }
  if (session.completionPercentage >= 70) return { label: 'جيدة جداً', stars: '★★★★☆' }
  if (session.completionPercentage >= 50) return { label: 'جيدة', stars: '★★★☆☆' }
  if (session.completionPercentage >= 30) return { label: 'محدودة', stars: '★★☆☆☆' }
  return { label: 'ضعيفة', stars: '★☆☆☆☆' }
}

function ProgressiveConversationCardImpl({ session }: Props) {
  const nextQuestion = useMemo(() => getNextBestQuestion(session), [session])
  const optionalQuestion = useMemo(() => getNextOptionalQuestion(session), [session])
  const missingFields = useMemo(() => getMissingFields(session), [session])
  const profileReady = useMemo(() => isDecisionProfileReady(session), [session])
  const confidence = useMemo(() => confidenceLevel(session), [session])
  const quality = useMemo(() => recommendationQuality(session), [session])

  const collectedCount = session.completedFields.length
  const totalCount = collectedCount + missingFields.length
  const collectedPercent = totalCount > 0 ? Math.round((collectedCount / totalCount) * 100) : 0

  return (
    <section
      aria-labelledby="conversation-heading"
      className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm"
    >
      <div className="mb-4 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-base">💬</span>
          <h3 id="conversation-heading" className="text-sm font-bold text-slate-900">
            تقدّم المحادثة
          </h3>
        </div>
        <span className={`rounded-full px-2.5 py-0.5 text-xs font-bold ${confidence.color}`}>
          ثقة: {confidence.label}
        </span>
      </div>

      {/* Completion progress bar */}
      <div className="mb-4">
        <div className="mb-1.5 flex items-center justify-between">
          <span className="text-xs font-medium text-slate-500">اكتمال البيانات</span>
          <span className="text-xs font-bold text-primary-600">{session.completionPercentage}%</span>
        </div>
        <div
          className="h-2 w-full overflow-hidden rounded-full bg-slate-100"
          role="progressbar"
          aria-valuenow={session.completionPercentage}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-label="نسبة اكتمال البيانات"
        >
          <div
            className="h-full rounded-full bg-gradient-to-l from-primary-400 to-primary-600 transition-all duration-700 ease-out"
            style={{ width: `${session.completionPercentage}%` }}
          />
        </div>
      </div>

      {/* Collected vs Missing */}
      <div className="mb-4 grid grid-cols-2 gap-3">
        <div className="rounded-xl bg-emerald-50 p-3">
          <p className="text-[10px] font-medium text-emerald-500">المعلومات المجموعة</p>
          <p className="mt-0.5 text-lg font-bold text-emerald-700">{collectedCount}</p>
          <div className="mt-1.5 h-1 overflow-hidden rounded-full bg-emerald-200/60">
            <div className="h-full rounded-full bg-emerald-500 transition-all duration-500" style={{ width: `${collectedPercent}%` }} />
          </div>
        </div>
        <div className="rounded-xl bg-rose-50 p-3">
          <p className="text-[10px] font-medium text-rose-500">المعلومات الناقصة</p>
          <p className="mt-0.5 text-lg font-bold text-rose-700">{missingFields.length}</p>
          <div className="mt-1.5 h-1 overflow-hidden rounded-full bg-rose-200/60">
            <div className="h-full rounded-full bg-rose-500 transition-all duration-500" style={{ width: `${100 - collectedPercent}%` }} />
          </div>
        </div>
      </div>

      {/* Missing fields list */}
      {missingFields.length > 0 && !profileReady && (
        <div className="mb-4">
          <p className="mb-2 text-xs font-semibold text-slate-600">الحقول الناقصة:</p>
          <div className="flex flex-wrap gap-1.5">
            {missingFields.map(field => (
              <span
                key={field}
                className="rounded-full border border-rose-100 bg-rose-50/50 px-2.5 py-1 text-[10px] font-medium text-rose-500"
              >
                {SESSION_FIELD_LABELS[field] ?? field}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Recommendation quality */}
      <div className="mb-4 rounded-xl border border-slate-100 bg-slate-50/50 p-3">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium text-slate-500">جودة التوصية المتوقعة</span>
          <div className="flex items-center gap-1.5">
            <span className="text-sm tracking-wider text-amber-400" dir="rtl">{quality.stars}</span>
            <span className="text-xs font-bold text-slate-700">{quality.label}</span>
          </div>
        </div>
      </div>

      {/* Next required question */}
      {nextQuestion && !profileReady && (
        <div className="rounded-xl border border-primary-100 bg-primary-50/50 p-4">
          <p className="text-xs font-bold text-primary-700">السؤال التالي المطلوب</p>
          <p className="mt-1.5 text-sm font-medium text-slate-700">{nextQuestion.text}</p>
          <div className="mt-3 flex items-start gap-2 border-t border-primary-100 pt-3">
            <span className="text-sm leading-6 text-primary-400">💡</span>
            <div>
              <p className="text-[10px] font-medium text-primary-500">لماذا أسأل هذا؟</p>
              <p className="mt-0.5 text-xs leading-relaxed text-slate-500">{nextQuestion.reason}</p>
            </div>
          </div>
        </div>
      )}

      {/* Profile ready but optional questions */}
      {profileReady && optionalQuestion && (
        <div className="rounded-xl border border-amber-100 bg-amber-50/40 p-4">
          <p className="text-xs font-bold text-amber-700">سؤال اختياري — يمكنك الإجابة أو تخطّيه</p>
          <p className="mt-1.5 text-sm font-medium text-slate-700">{optionalQuestion.text}</p>
        </div>
      )}

      {/* Profile ready and no more questions */}
      {profileReady && !optionalQuestion && (
        <div className="rounded-xl border border-success-200 bg-success-50 p-4 text-center">
          <p className="text-sm font-bold text-success-700">
            اكتملت كل المعلومات الأساسية! رحّال جاهز للبحث.
          </p>
        </div>
      )}
    </section>
  )
}

export const ProgressiveConversationCard = memo(ProgressiveConversationCardImpl)

