interface Props {
  rankedOptions: NormalizedTravelOption[]
  reasoningResults: Map<string, ReasoningResult>
}

export default function ResultsExperience({ rankedOptions, reasoningResults }: Props) {
  const [sortKey, setSortKey] = useState<SortKey>('best')
  const [filters, setFilters] = useState<FilterState>({
    maxPrice: null,
    maxDuration: null,
    maxStops: null,
    departureWindow: 'any',
    arrivalWindow: 'any',
    airline: null,
    recType: null,
  })

  const reports = useMemo(
    () => buildFullReport(rankedOptions, reasoningResults),
    [rankedOptions, reasoningResults]
  )

  const filtered = useMemo(() => {
    let result = [...rankedOptions]
    if (filters.maxPrice !== null) result = result.filter(o => o.price <= filters.maxPrice!)
    if (filters.maxDuration !== null) result = result.filter(o => o.durationMinutes === null || o.durationMinutes <= filters.maxDuration!)
    if (filters.maxStops !== null) result = result.filter(o => o.stops === null || o.stops <= filters.maxStops!)
    if (filters.departureWindow !== 'any') result = result.filter(o => inWindow(String(o.attributes.departureTime), filters.departureWindow as 'morning' | 'afternoon' | 'evening'))
    if (filters.arrivalWindow !== 'any') result = result.filter(o => inWindow(String(o.attributes.arrivalTime), filters.arrivalWindow as 'morning' | 'afternoon' | 'evening'))
    if (filters.airline) result = result.filter(o => o.attributes.airline === filters.airline)
    if (filters.recType) result = result.filter(o => o.recommendationLevel === filters.recType)
    return sortOptions(result, sortKey)
  }, [rankedOptions, filters, sortKey])

  const bestOption = rankedOptions[0]
  const bestReport = reports[0]

  if (!bestOption || !bestReport) return null

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <span className="text-lg">🏆</span>
        <h2 className="text-base font-bold text-slate-900">نتائج رحّال</h2>
      </div>

      <div className="rounded-lg border border-amber-200 bg-amber-50/60 px-4 py-2.5">
        <p className="text-xs font-medium text-amber-700">
          بيانات تجريبية — لم يتم ربط مزودي السفر بعد
        </p>
      </div>

      {/* Rahhal Recommendation Panel */}
      <RahhalRecommendationPanel bestOption={bestOption} report={bestReport} allOptions={rankedOptions} />

      {/* Sort bar */}
      <div className="flex items-center gap-2 overflow-x-auto pb-1">
        <span className="shrink-0 text-xs font-medium text-slate-400">ترتيب:</span>
        {(Object.keys(SORT_LABELS) as SortKey[]).map(key => (
          <button
            key={key}
            type="button"
            onClick={() => setSortKey(key)}
            className={`shrink-0 rounded-full px-3 py-1 text-[11px] font-medium transition-all duration-200 ${
              sortKey === key
                ? 'bg-primary-600 text-white shadow-sm'
                : 'border border-slate-200 bg-white text-slate-500 hover:border-primary-300 hover:text-primary-600'
            }`}
          >
            {SORT_LABELS[key]}
          </button>
        ))}
      </div>

      {/* Filters */}
      <FilterBar filters={filters} onChange={setFilters} options={rankedOptions} />

      {/* Results count */}
      <div className="flex items-center justify-between">
        <p className="text-xs text-slate-400">
          {filtered.length} من {rankedOptions.length} خيار
        </p>
      </div>

      {/* Cards */}
      <div className="grid grid-cols-1 gap-3">
        {filtered.length === 0 ? (
          <div className="rounded-2xl border border-slate-200 bg-slate-50 px-5 py-8 text-center">
            <p className="text-sm font-medium text-slate-400">لا توجد نتائج مطابقة للتصفية</p>
          </div>
        ) : (
          filtered.map(option => {
            const badges = determineBadges(option, rankedOptions)
            if (option.type === 'flight') {
              return <FlightCard key={option.id} option={option} badges={badges} />
            }
            return <NonFlightCard key={option.id} option={option} badges={badges} />
          })
        )}
      </div>
    </div>
  )
}

import { memo, useMemo } from 'react'
import type { NormalizedTravelOption } from '../utils/searchOrchestrator'
import type { ReasoningResult } from '../utils/reasoningEngine'
import type { FinalDecisionScore, ScoreCategory } from '../utils/decisionScoreEngine'
import { scoreToStars, formatStars } from '../utils/reportFormatter'

interface Props {
  option: NormalizedTravelOption
  reasoning: ReasoningResult
}

const CATEGORY_LABELS: Record<ScoreCategory, string> = {
  price: 'مطابقة الميزانية',
  comfort: 'جودة الراحة',
  travelTime: 'كفاءة وقت السفر',
  familySuitability: 'ملاءمة العائلة',
  luxury: 'مستوى الفخامة',
  destinationMatch: 'مطابقة الوجهة',
  purposeMatch: 'مطابقة الغرض',
  preferenceMatch: 'مطابقة التفضيلات',
}

const CATEGORY_ICONS: Record<ScoreCategory, string> = {
  price: '💰',
  comfort: '🛋️',
  travelTime: '⏱️',
  familySuitability: '👨‍👩‍👧',
  luxury: '💎',
  destinationMatch: '📍',
  purposeMatch: '🎯',
  preferenceMatch: '⚙️',
}

function scoreColor(score: number): string {
  if (score >= 75) return 'text-emerald-600 bg-emerald-50'
  if (score >= 50) return 'text-amber-600 bg-amber-50'
  return 'text-rose-500 bg-rose-50'
}

function barColor(score: number): string {
  if (score >= 75) return 'bg-emerald-500'
  if (score >= 50) return 'bg-amber-500'
  return 'bg-rose-400'
}

function ScoreBreakdownCardImpl({ option, reasoning }: Props) {
  const score: FinalDecisionScore | null = option.decisionScore

  const categories = useMemo(() => {
    if (!score) return []
    return score.categories
  }, [score])

  const overallStars = scoreToStars(score?.weightedAverage ?? 0)
  const starsDisplay = formatStars(overallStars)

  return (
    <div
      role="region"
      aria-label={`تفصيل النقاط لـ ${option.title}`}
      className="grid grid-cols-1 gap-3 sm:grid-cols-2"
    >
      {categories.map(cat => {
        const stars = scoreToStars(cat.score)
        const starsDisp = formatStars(stars)
        return (
          <div
            key={cat.category}
            className="rounded-xl border border-slate-100 bg-white p-3.5 transition-all duration-200 hover:border-slate-200 hover:shadow-sm"
          >
            <div className="mb-2 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <span className="text-sm" aria-hidden>{CATEGORY_ICONS[cat.category]}</span>
                <span className="text-xs font-semibold text-slate-700">
                  {CATEGORY_LABELS[cat.category] ?? cat.category}
                </span>
              </div>
              <span className={`rounded-lg px-2 py-0.5 text-xs font-bold ${scoreColor(cat.score)}`} dir="ltr">
                {cat.score}/100
              </span>
            </div>
            <div className="mb-2 flex items-center justify-between">
              <span className="text-[11px] tracking-wider text-amber-400" dir="rtl" aria-label={`${stars.label}`}>
                {starsDisp.visual}
              </span>
              <span className="text-[10px] text-slate-400">{stars.label}</span>
            </div>
            <div
              className="h-1.5 w-full overflow-hidden rounded-full bg-slate-100"
              role="progressbar"
              aria-valuenow={cat.score}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-label={CATEGORY_LABELS[cat.category]}
            >
              <div
                className={`h-full rounded-full transition-all duration-700 ease-out ${barColor(cat.score)}`}
                style={{ width: `${cat.score}%` }}
              />
            </div>
            {cat.reason && (
              <p className="mt-1.5 text-[10px] leading-relaxed text-slate-400">{cat.reason}</p>
            )}
          </div>
        )
      })}

      {/* Overall experience */}
      <div className="rounded-xl border border-primary-100 bg-primary-50/40 p-3.5 sm:col-span-2">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-sm" aria-hidden>✨</span>
            <span className="text-xs font-bold text-primary-700">التجربة الإجمالية المقدّرة</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[11px] tracking-wider text-amber-400" dir="rtl">{starsDisplay.visual}</span>
            <span className="text-xs font-bold text-primary-600" dir="ltr">{score?.weightedAverage ?? 0}/100</span>
          </div>
        </div>
        <p className="mt-1.5 text-[10px] leading-relaxed text-primary-500">
          {reasoning.recommendationSummary[0]
            ? reasoning.recommendationSummary[0].key.includes('excellent') ? 'خيار استثنائي يلبي معظم احتياجاتك'
              : reasoning.recommendationSummary[0].key.includes('recommended') ? 'خيار قوي يلبي احتياجاتك الأساسية'
              : 'خيار مقبول مع بعض التنازلات'
            : 'تقييم إجمالي بناءً على جميع المعايير'}
        </p>
      </div>
    </div>
  )
}

export const ScoreBreakdownCard = memo(ScoreBreakdownCardImpl)

import { memo, useState, useEffect, useCallback } from 'react'
import { searchHistoryRepository, favoriteRepository } from '../lib/repositories'
import type { SearchHistoryRow } from '../lib/types'

interface Props {
  onContinueSearch: (row: SearchHistoryRow) => void
  refreshKey: number
}

function SearchHistoryPanelImpl({ onContinueSearch, refreshKey }: Props) {
  const [history, setHistory] = useState<SearchHistoryRow[]>([])
  const [favorites, setFavorites] = useState<string[]>([])
  const [loading, setLoading] = useState(true)
  const [pinned, setPinned] = useState<Set<string>>(new Set())

  const loadData = useCallback(async () => {
    setLoading(true)
    try {
      const [rows, favs] = await Promise.all([
        searchHistoryRepository.listByUser(10),
        favoriteRepository.listByUser(),
      ])
      setHistory(rows)
      setFavorites(favs.map(f => f.destination))
    } catch {
      setHistory([])
      setFavorites([])
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadData()
  }, [loadData, refreshKey])

  const handleDelete = async (id: string) => {
    try {
      await searchHistoryRepository.delete(id)
      setHistory(prev => prev.filter(r => r.id !== id))
    } catch { }
  }

  const handleToggleFavorite = async (destination: string) => {
    try {
      if (favorites.includes(destination)) {
        await favoriteRepository.deleteByDestination(destination)
        setFavorites(prev => prev.filter(d => d !== destination))
      } else {
        await favoriteRepository.create({ destination })
        setFavorites(prev => [...prev, destination])
      }
    } catch { }
  }

  const handleTogglePin = (id: string) => {
    setPinned(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const sortedHistory = [
    ...history.filter(r => pinned.has(r.id)),
    ...history.filter(r => !pinned.has(r.id)),
  ]

  return (
    <section
      aria-labelledby="history-heading"
      className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm"
    >
      <div className="mb-4 flex items-center gap-2">
        <span className="text-base">🕘</span>
        <h3 id="history-heading" className="text-sm font-bold text-slate-900">سجل البحث</h3>
      </div>

      {loading ? (
        <div className="space-y-2" aria-label="جاري تحميل السجل">
          {[1, 2, 3].map(i => (
            <div key={i} className="flex animate-pulse items-center gap-3 rounded-xl border border-slate-100 p-3">
              <div className="h-8 w-8 rounded-lg bg-slate-100" />
              <div className="flex-1 space-y-1.5">
                <div className="h-3 w-3/4 rounded bg-slate-100" />
                <div className="h-2 w-1/2 rounded bg-slate-50" />
              </div>
            </div>
          ))}
        </div>
      ) : sortedHistory.length === 0 ? (
        <div className="rounded-xl border border-dashed border-slate-200 py-8 text-center">
          <span className="text-2xl">🔍</span>
          <p className="mt-2 text-xs text-slate-400">لا توجد عمليات بحث سابقة</p>
        </div>
      ) : (
        <div className="space-y-2">
          {sortedHistory.map(row => (
            <div
              key={row.id}
              className="group flex items-center gap-3 rounded-xl border border-slate-100 p-3 transition-all duration-200 hover:border-primary-200 hover:bg-primary-50/30"
            >
              <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-slate-50 text-sm font-bold text-slate-400 transition-colors group-hover:bg-primary-100 group-hover:text-primary-600">
                {pinned.has(row.id) ? '📌' : '🔎'}
              </div>

              <button
                type="button"
                onClick={() => onContinueSearch(row)}
                className="min-w-0 flex-1 text-right"
                aria-label={`متابعة البحث عن ${row.destination}`}
              >
                <p className="truncate text-xs font-bold text-slate-800 group-hover:text-primary-700">
                  {row.destination || 'غير محدد'}
                </p>
                <p className="text-[10px] text-slate-400">
                  {row.result_count} نتيجة · {new Date(row.created_at).toLocaleDateString('ar-SA')}
                </p>
              </button>

              <div className="flex items-center gap-1 opacity-0 transition-opacity duration-200 group-hover:opacity-100">
                <button
                  type="button"
                  onClick={() => handleTogglePin(row.id)}
                  className="flex h-7 w-7 items-center justify-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-600"
                  aria-label={pinned.has(row.id) ? 'إلغاء التثبيت' : 'تثبيت البحث'}
                  title={pinned.has(row.id) ? 'إلغاء التثبيت' : 'تثبيت'}
                >
                  📌
                </button>
                <button
                  type="button"
                  onClick={() => handleToggleFavorite(row.destination)}
                  className="flex h-7 w-7 items-center justify-center rounded-lg text-slate-400 hover:bg-amber-50 hover:text-amber-500"
                  aria-label={favorites.includes(row.destination) ? 'إزالة من المفضلة' : 'إضافة للمفضلة'}
                  title="مفضلة"
                >
                  {favorites.includes(row.destination) ? '★' : '☆'}
                </button>
                <button
                  type="button"
                  onClick={() => handleDelete(row.id)}
                  className="flex h-7 w-7 items-center justify-center rounded-lg text-slate-400 hover:bg-rose-50 hover:text-rose-500"
                  aria-label="حذف البحث"
                  title="حذف"
                >
                  <svg viewBox="0 0 24 24" className="h-3.5 w-3.5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M3 6h18M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2" />
                  </svg>
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </section>
  )
}

